import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as l,o as t,c as o,a3 as i}from"./chunks/framework.DdpBa4_E.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/29-相刺第二十.md","filePath":"books/yan-tie-lun/29-相刺第二十.md","lastUpdated":1794316978000}'),n={name:"books/yan-tie-lun/29-相刺第二十.md"};function s(r,a,e,_,c,d){return t(),o("div",null,[...a[0]||(a[0]=[i('<p>相刺第二十 【题解】</p><p>本篇记载大夫与文学之间互相讽刺。大夫攻击儒生口诵尧舜，专门学习那些不能应验的空话，对国家治理毫无益处，华而不实，口是心非，能说不能行，往来游逛，不耕而食，不织而衣，欺骗良民百姓，耽误农时，妨害朝政，成为当代社会一大祸患。文学则辩称社会有君子与小人的分工，不可能每个人都去耕织。儒生之所以在现实政治生活中未能发挥重大作用，是因为有些君主不听劝谏，排斥圣贤。文学进一步指出，当今朝廷执政公卿的道德并不高尚，这是朝政昏暗的重要原因。</p><p>大夫曰：“古者，经井田[(1)]，制廛里[(2)]，丈夫治其田畴[(3)]，女子治其麻枲[(4)]，无旷地，无游人[(5)]。故非商工不得食于利末[(6)]，非良农不得食于收获，非执政不得食于官爵。今儒者释耒耜而学不验之语[(7)]，旷日弥久，而无益于治[(8)]，往来浮游[(9)]，不耕而食，不蚕而衣，巧伪良民[(10)]，以夺农妨政[(11)]，此亦当世之所患也。”</p><p>【注释】</p><p>[(1)]经：经营，划分。井田：《孟子·滕文公上》：“方里而井，井九百亩，其中为公田；八家皆私百亩，同养公田。公事毕，然后敢治私事，所以别野人也。”</p><p>[(2)]廛（chán）里：住宅。廛，古代平民一户人家所占有的房地。</p><p>[(3)]丈夫：男人。田畴：田地。</p><p>[(4)]治其麻枲（xǐ）：纺织麻布。</p><p>[(5)]游人：游手好闲的人。</p><p>[(6)]利末：指工商利润。</p><p>[(7)]释：放下。耒耜（sì）：泛指农具。不验之语：不能应验的空话。</p><p>[(8)]治：原作“理”，据王利器说校改。</p><p>[(9)]浮游：游逛。</p><p>[(10)]巧伪：欺骗。</p><p>[(11)]夺农：耽误农时。妨政：妨害朝政。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“古时候，经营井田，规定住宅，男人耕田种地，女子纺织麻布，没有荒废不种的土地，没有游手好闲的人。因此如果不是商人工匠，就不能依靠工商利润生活；如果不是种田好手，就不能依靠收获庄稼生活；如果不是执掌政权，就不能依靠官爵俸禄生活。如今儒生放下农具，专门学习那些不能应验的空话，旷日持久，对国家治理毫无益处，往来游逛，不耕种而吃饭，不养蚕而穿衣，欺骗良民百姓，耽误农时，妨害朝政，这也是当代所忧患的啊。”</p><p>文学曰：“禹慼洪水[(1)]，身亲其劳[(2)]，泽行路宿[(3)]，过门不入。当此之时，簪堕不掇[(4)]，冠挂不顾[(5)]，而暇耕乎[(6)]？孔子曰：‘诗人疾之不能默，丘疾之不能伏。’[(7)]是以东西南北七十说而不用[(8)]，然后退而修王道[(9)]，作《春秋》，垂之万载之后[(10)]，天下折中焉[(11)]，岂与匹夫匹妇耕织同哉！《传》曰：‘君子当时不动，而民无观也。’[(12)]故非君子莫治小人，非小人无以养君子[(13)]，不当耕织为匹夫匹妇也[(14)]。君子耕而不学，则乱之道也。”</p><p>【注释】</p><p>[(1)]慼（qī）：忧虑。原作“蹙”，据王先谦说校改。</p><p>[(2)]身亲其劳：亲身参加治水的劳动。</p><p>[(3)]泽行：在水中行走。路宿：在路边住宿。一说，路宿，通“露宿”。</p><p>[(4)]簪（zān）：束发的簪子。堕：掉落。不掇：不捡起来。《淮南子·原道训》：“禹之趋时也，履遗而费（弗）取，冠挂而费（弗）顾。”</p><p>[(5)]冠挂：帽子被树枝挂掉。</p><p>[(6)]暇：空余时间。</p><p>[(7)]诗人疾之不能默，丘疾之不能伏：未见出处。疾，痛恨。不能默，不能保持沉默。丘，孔子自称。不能伏，不能隐伏不问。</p><p>[(8)]七十说：游说了七十个诸侯。《淮南子·泰族训》：“孔子欲行王道，东西南北七十说而不遇。”据《史记·孔子世家》，孔子游说的诸侯国有卫、宋、陈、曹、蔡等。说孔子游说七十诸侯，是战国秦汉儒生的夸大之词。</p><p>[(9)]退：指孔子周游列国十四年之后返回鲁国。</p><p>[(10)]垂：垂示，流传。万载：万年。</p><p>[(11)]折中：指以《春秋》作为判断是非的标准。《史记·孔子世家》：“自天子王侯，中国言六艺者折中于夫子，可谓至圣矣！”</p><p>[(12)]君子当时不动，而民无观也：未见出处。不动，指不从事政治学术活动。无观，无法观摩考察。</p><p>[(13)]故非君子莫治小人，非小人无以养君子：《孟子·滕文公上》：“无君子莫治野人，无野人莫养君子。”小人，指普通民众。</p><p>[(14)]不当：原作“当不”，据姚范、俞樾说校改。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“禹忧虑洪水，亲身参加治水劳动，在水泽中行走，在路边住宿，三过家门而不入。那个时候，束发的簪子掉落了也来不及拾取，帽子被树枝挂掉也顾不上管，哪里有空余时间耕田呢？孔子说：‘诗人痛恨现实而不能保持沉默，我孔丘痛恨现实而不能隐伏不问。’所以他东西南北奔走，游说了七十个诸侯，但没有人用他，然后返回鲁国阐述王道，作《春秋》，流传到万年之后，天下人谈论六艺都要以孔子言论作为判断是非的标准，怎么能与普通老百姓男耕女织等同呢！传记上说：‘君子当时不从事政治学术活动，民众就无从观瞻考察。’因此没有君子就没有人治理小人，没有小人就无法养活君子。君子不应当像普通老百姓那样去从事耕织。君子耕田而不学道，那是导致社会混乱的途径。”</p><p>大夫曰：“文学言治尚于唐、虞[(1)]，言义高于秋天[(2)]，有华言矣[(3)]，未见其实也[(4)]。昔鲁穆公之时[(5)]，公仪为相[(6)]，子思、子柳为之卿[(7)]，然北削于齐，以泗为境[(8)]，南畏楚人，西宾秦国[(9)]。孟轲居梁[(10)]，兵折于齐[(11)]，上将军死[(12)]，而太子虏[(13)]，西败于秦[(14)]，地夺壤削，亡河内、河外[(15)]。夫仲尼之门，七十子之徒，去父母，捐室家[(16)]，负荷而随孔子[(17)]，不耕而学，乱乃愈滋。故玉屑满箧[(18)]，不为有宝；诗书负笈[(19)]，不为有道。要在安国家，利人民，不苟繁文众辞而已[(20)]。”</p><p>【注释】</p><p>[(1)]尚：超过。唐、虞：唐尧、虞舜。</p><p>[(2)]秋天：秋季天空。</p><p>[(3)]华言：华丽的言辞。</p><p>[(4)]实：实效。</p><p>[(5)]鲁穆公：战国时期鲁国国君，姬姓，名显，鲁元公之子。</p><p>[(6)]公仪：即公仪休。《史记·循吏列传》载：“公仪休者，鲁博士也。以高弟为鲁相。奉法循理，无所变更，百官自正。使食禄者不得与下民争利，受大者不得取小。”</p><p>[(7)]子思：孔子之孙，名伋。子柳：原作“子原”，据卢文弨说校改。《孟子·告子下》：“鲁穆公之时，公仪子为政，子柳、子思为臣，鲁之削也滋甚。”</p><p>[(8)]泗：泗水。</p><p>[(9)]宾：宾服，服从。</p><p>[(10)]孟轲：即孟子，战国中期儒家大师。梁：即魏国。</p><p>[(11)]兵折于齐：公元前344年—前343年，魏国与齐国在马陵（今河南范县）相遇，齐国用孙膑之计大败魏军，魏将庞涓被擒，太子申被俘。</p><p>[(12)]上将军：指庞涓。</p><p>[(13)]太子：太子申。</p><p>[(14)]西败于秦：公元前341年，商鞅率秦军攻魏。公元前330年，秦公孙衍攻魏。公元前290年，秦将白起攻魏。魏割让黄河两岸的土地给秦国。</p><p>[(15)]河内、河外：指山西、陕西两省交界处南段黄河以东和以西的地方。《孟子·梁惠王上》：“梁惠王曰：‘及寡人之身，东败于齐，长子死焉；西丧地于秦七百里；南辱于楚。’”</p><p>[(16)]捐：扔下。</p><p>[(17)]负荷：肩挑书籍。</p><p>[(18)]玉屑：玉石碎末。箧（qiè）：箱子。</p><p>[(19)]诗书：原作“诵诗书”，据王利器说校改。笈（jí）：背在背上的竹制书箱。</p><p>[(20)]繁文众辞：繁缛言辞。繁文，原作“文繁”，据黄侃说校正。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“文学谈论国家治理，似乎要超过唐尧、虞舜，讲述道义要高于秋季天空，但只有华丽的言辞，没有看到实效。从前鲁穆公时期，儒生公仪休为宰相，子思、子柳担任鲁国大夫，然而鲁国北边领土被齐国侵占，以泗水为鲁国北境；南边畏惧楚国人；西边服从秦国。孟轲在魏国时，魏国军队被齐国打败，上将军庞涓战死，而太子申被俘虏；西边败于秦国，土地被侵夺，疆域被削减，丧失了河内、河外的土地。仲尼门下有七十子之徒，他们离开父母，丢下妻室儿女，肩挑书籍跟随孔子，不耕田而学礼，混乱于是更加严重。因而满箱珠玉，不能说拥有珍宝；背着满箱诗书，不能说拥有道义。关键在于安定国家，有利人民，不只是口头的繁文缛辞而已。”</p><p>文学曰：“虞不用百里奚之谋而灭，秦穆用之以至霸焉。夫不用贤则亡，而不削何可得乎[(1)]？孟子适梁，惠王问利，答以仁义[(2)]。趣舍不合[(3)]，是以不用而去，怀宝而无语[(4)]。故有粟不食，无益于饥；睹贤不用，无益于削。纣之时，内有微、箕二子[(5)]，外有胶鬲、棘子[(6)]，故其不能存。夫言而不用，谏而不听，虽贤，恶得有益于治也[(7)]？”</p><p>【注释】</p><p>[(1)]虞不用百里奚之谋而灭，秦穆用之以至霸焉。夫不用贤则亡，而不削何可得乎：《孟子·告子下》：“虞不用百里奚而亡，秦穆公用之而霸，不用贤则亡，削何可得与？”</p><p>[(2)]孟子适梁，惠王问利，答以仁义：《孟子·梁惠王上》：“孟子见梁惠王，王曰：‘叟，不远千里而来，亦将有以利吾国乎？’孟子对曰：‘王何必曰利，亦有仁义而已矣。’”梁，即魏国。</p><p>[(3)]趣舍：取舍。趣，通“取”。</p><p>[(4)]怀宝而无语：“怀宝”上原有“夫”字，据王先谦说校删。怀宝，指怀揣正确的治国思想。《论语·阳货》载阳货曰：“怀其宝而迷其邦。”</p><p>[(5)]微：微子，殷纣王庶兄。箕：箕子，殷纣王亲戚。</p><p>[(6)]胶鬲（ɡé）：殷纣王大臣，后投奔周文王。棘子：《庄子·逍遥游》：“且汤之问棘也是已。”此处棘子，或许是汤时棘子的后人。</p><p>[(7)]恶得：怎么能够。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“当年虞国不采用百里奚的计谋而灭亡，秦穆公采用百里奚的计谋而称霸。不任用贤能就会灭亡，不削弱又怎么可能呢？当年孟子来到魏国，魏惠王问孟子带来什么利益，孟子以仁义来回答魏惠王。两人取舍不合，所以孟子主张不被采用而离开，怀揣治国之宝而无处可说。因而有粮食而不吃，无益于解决饥饿问题；看到贤能而不能任用，无益于解决国土削减问题。殷纣王时期，宗亲大臣有微子和箕子，朝廷大臣有胶鬲和棘子，因此殷商王朝不能生存，是因为贤臣建言不被采用，贤臣劝谏而不听，即使国家有贤能，怎么能够对治理国家有帮助呢？”</p><p>大夫曰：“橘柚生于江南，而民皆甘之于口，味同也；好音生于郑、卫[(1)]，而人皆乐之于耳，声同也[(2)]。越人子臧、戎人由余[(3)]，待译而后通[(4)]，而并显齐、秦[(5)]，人之心于善恶同也。故曾子倚山而吟[(6)]，山鸟下翔；师旷鼓琴[(7)]，百兽率舞[(8)]。未有善而不合，诚而不应者也。意未诚与？何故言而不见从，行而不合也？”</p><p>【注释】</p><p>[(1)]郑、卫：春秋时期，郑、卫两国流行一种新音乐，这种音乐与传统雅乐的风格完全不同，受到人们普遍喜爱，被人们称之为郑、卫之音。</p><p>[(2)]声同：听觉相同。</p><p>[(3)]子臧：原作“夷吾”，据张敦仁说校改。由余：春秋时期戎人，后来降秦，受到秦穆公重用，秦穆公用由余计谋称霸西戎。</p><p>[(4)]通：沟通，交流。</p><p>[(5)]显：显耀。</p><p>[(6)]曾子：曾参，孔子弟子，以孝道著称。据《吕氏春秋·必己》载，曾参极尽孝道，但仍受到父亲的怀疑。曾参就走到山里去，靠着山坡高声吟唱诗歌，表达悲叹之情。</p><p>[(7)]师旷：晋国著名乐师。据《韩非子·十过》载，师旷善于鼓琴，鼓琴时，有玄鹤十六只从南方飞来，引颈而鸣，舒翼而舞。</p><p>[(8)]百兽率舞：见于《尚书·尧典》。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“橘子和柚子生于长江以南，人们都觉得甘甜可口，这是因为人们的味觉相同。美妙的音乐产生于郑、卫之地，人们都觉得动听悦耳，这是因为人们的听觉相同。越国人子臧、西戎人由余，需要等到有人翻译而后才能交流，而他们都先后贵显于齐国和秦国，这是因为人心对善恶的看法相同。因此曾参靠着山石吟诵诗歌，山里的鸟儿都飞下来倾听；晋国乐师师旷弹琴，各种野兽都为之起舞。从来没有善良而不能投合，诚恳而没有感应的情形。恐怕是心意不够诚恳吧？为什么说话而无人听从，所作所为与人不合呢？”</p><p>文学曰：“扁鹊不能治不受针药之疾，贤圣不能正不食谏诤之君[(1)]。故桀有关龙逢而夏亡[(2)]，纣有三仁而商灭[(3)]，故不患无由余、子臧之论[(4)]，患无桓、穆之听耳[(5)]。是以孔子东西无所遇[(6)]，屈原放逐于楚国也[(7)]。故曰：‘直道而事人，焉往而不三黜[(8)]？枉道而事人，何必去父母之邦[(9)]？’此所以言而不见从，行而不得合者也[(10)]。”</p><p>【注释】</p><p>[(1)]不食：不接受。谏诤：直言劝谏。</p><p>[(2)]关龙逢：夏朝大臣，因力谏夏桀而被杀害。逢，一作“逄”。夏亡：原作“亡夏”，据王先谦、王利器说校改。</p><p>[(3)]纣有三仁：指比干、箕子、微子。《论语·微子》：“微子去之，箕子为之奴，比干谏而死。孔子曰：‘殷有三仁焉。’”纣，原作“殷”；仁，原作“人”，据王利器说校改。</p><p>[(4)]故不患无由余、子臧之论：“故”字原无，据王利器说校补。子臧，原作“夷吾”，据张敦仁说校改。论，原作“伦”，据王利器说校改。</p><p>[(5)]桓：齐桓公。穆：秦穆公。</p><p>[(6)]遇：原作“适遇”，据王利器说删“适”字。</p><p>[(7)]屈原放逐于楚国也：“也”字原无，据王利器说校补。</p><p>[(8)]黜：罢免。</p><p>[(9)]何必去父母之邦：此句原脱，据王利器说校补。</p><p>[(10)]此所以言而不见从，行而不得合者也：原作“终非以此言而不见从，行而不合者也”，据王利器说校改。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“扁鹊不能治疗那些针灸用药都不见效的疾病，圣贤不能规正那些听不进直言劝谏的君主。因此，夏桀虽然有关龙逢这样的忠臣，但夏朝仍然灭亡；殷纣王虽然有比干、箕子、微子三位仁人，但殷商王朝仍然覆灭。所以，不怕没有由余、子臧正确的议论，就怕没有齐桓公、秦穆公这样善于听取意见的君主。因此孔子才东奔西走一无所遇，屈原才被楚王放逐。所以有人说：‘按照正直之道去事奉君主，到哪里不是屡次被罢黜？按照邪曲之道去事奉君主，何必要离开父母所在的邦国？’这就是儒生说话无人听从，所作所为与人不合的原因啊。”</p><p>大夫曰：“歌者不期于利声[(1)]，而贵在中节[(2)]；论者不期于丽辞，而务在事实。善声而不知转[(3)]，未可为能歌也[(4)]；善言而不知变，未可谓能说也。持规而非矩[(5)]，执准而非绳[(6)]，通一孔[(7)]，晓一理，而不知权衡，以所不睹不信人[(8)]，若蝉之不知雪，坚据古文以应当世[(9)]，犹辰参之错[(10)]，胶柱而调瑟[(11)]，固而难合矣[(12)]。孔子所以不用于世，而孟轲见贱于诸侯也。”</p><p>【注释】</p><p>[(1)]利声：尖利的声音。</p><p>[(2)]中节：合于节拍。</p><p>[(3)]善声：声音好听。转：指曲调变换。一说，转，曲调。</p><p>[(4)]为：通“谓”。</p><p>[(5)]规：圆规，画圆的器具。矩：曲尺，画方的器具。</p><p>[(6)]准：测定水平面的器具。绳：木匠用以取直的墨线。</p><p>[(7)]通一孔：指一孔之见。孔，小洞。</p><p>[(8)]以所不睹不信人：因为自己没有亲眼看见就不相信别人。</p><p>[(9)]坚据古文：顽固地根据古代文献。</p><p>[(10)]辰参（shēn）：二十八宿中的两个星辰。辰星出现在天空的东方，参星出现在天空的西方，两者不能同时出现。</p><p>[(11)]胶柱而调瑟：即胶柱鼓瑟，比喻拘泥而不知变通。</p><p>[(12)]难合：难以合拍。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“歌手不期望声音尖利，而贵在合于曲调节拍；辩论的人不期待他的华丽辞藻，而务在实事求是。声音好听而不知道曲调的转换，不能说他善于唱歌；善于言辞而不知变化，不能说他善于说话。手持画圆的圆规而否定画方的曲尺，拿着水平仪而否定取直的绳墨，只有一孔之见，只知道一个道理，而不知道权衡得失，因为自己没有亲眼看见就不相信别人，如同夏蝉不知道冬雪，顽固地根据古代文献来应对当世情况，犹如辰星、参星永远相错而不相合，胶柱鼓瑟，当然就难以合拍了。这就是孔子不被当时诸侯任用，而孟轲被当时诸侯轻视的原因啊。”</p><p>文学曰：“日月之光，而盲者不能见，雷电之声，而聋人不能闻。夫为不知音者言，若语于喑聋[(1)]，何特蝉之不知重雪耶[(2)]？夫以伊尹之智，太公之贤，而不能开辞于桀、纣[(3)]，非说者非[(4)]，听者过也。是以荆和抱璞而泣血[(5)]，曰：‘安得良工而剖之！’屈原行吟泽畔，曰：‘安得皋陶而察之[(6)]！’夫人君莫不欲求贤以自辅[(7)]，任能以治国，然牵于流说[(8)]，惑于道谀[(9)]，是以贤圣蔽掩[(10)]，而谗佞用事[(11)]，以此亡国破家，而贤士饥于岩穴也[(12)]。昔赵高无过人之志[(13)]，而居万人之位，是以倾覆秦国而祸殃其宗，尽失其瑟，何胶柱之调也？”</p><p>【注释】</p><p>[(1)]喑（yīn）：哑巴。</p><p>[(2)]何特：岂止。重雪：大雪，多雪。</p><p>[(3)]开辞：进言规劝。</p><p>[(4)]者非：原作“也非”，据王利器说校改。</p><p>[(5)]荆和抱璞而泣血：据《韩非子·和氏》载，春秋楚人卞和得到一块玉璞，献给楚厉王，楚厉王认为是石头，命人砍掉卞和的左脚。楚武王即位后，卞和又去献玉璞，结果又被砍去右脚。楚文王即位后，卞和抱着玉璞到荆山中哭了三天三夜，泪尽出血。楚文王听说后，命人剖璞，果然是稀世珍宝，遂命名为“和氏璧”。</p><p>[(6)]安得皋陶（ɡāo yáo）而察之：《楚辞·九章》：“俾山川以备御兮，命咎繇使听直。”咎繇，即“皋陶”，为帝舜时期法官。屈原自感冤屈深重，希望有皋陶那样正直的法官来断明是非曲直。</p><p>[(7)]夫人君莫不欲求贤以自辅：《史记·屈原贾生列传》：“人君无愚智贤不肖，莫不欲求忠以自为，举贤以自佐，然亡国破家相随属，而圣君治国累世而不见者，其所谓忠者不忠，而所谓贤者不贤也。”</p><p>[(8)]牵：牵制。流说：流言蜚语。</p><p>[(9)]道谀：谄谀。</p><p>[(10)]蔽掩：掩盖。</p><p>[(11)]谗佞：进谗言、巧言谄媚的人。此处指奸臣。</p><p>[(12)]岩穴：岩洞。古代贤士往往隐居山中。</p><p>[(13)]志：识。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“日月的光华，盲人看不见，雷电的声光，聋子听不见。对不是知音的人说话，如同对聋哑人说话，岂止是夏蝉不知冬天的厚雪呢？凭借伊尹的智慧，姜太公的贤能，却不能规劝夏桀和殷纣王，这不是劝谏者的过错，而是听者的过错。所以卞和抱着玉璞在荆山下哭泣得眼睛流血，说：‘哪里有优秀的玉匠剖开这块玉璞！’屈原在湖边泽畔一边流浪一边吟诗，说：‘哪里能有皋陶这样的法官来体察我的冤情！’凡是君主，没有人不希望求得贤才来辅佐自己，任用贤能来治国，然而大都被流言蜚语所束缚，被阿谀奉承所迷惑，所以圣贤被掩盖，而那些进谗言、献谄媚的奸臣掌握政权，因此一个个君主亡国破家，而贤士在深山岩洞里忍饥挨饿。从前赵高并没有过人的见识，却居于一人之下万人之上的地位，所以导致秦国覆灭，他的宗族也遭受祸殃。连琴瑟都丢掉了，哪里有什么胶柱可以调理呢？”</p><p>大夫曰：“所谓文学高第者[(1)]，智略能明先王之术[(2)]，而姿质足以履行其道[(3)]。故居则为人师[(4)]，用则为世法[(5)]。今文学言治则称尧、舜，道行则言孔、墨[(6)]，授之政则不达[(7)]，怀古道而不能行，言直而行枉[(8)]，道是而情非，衣冠有以殊于乡曲[(9)]，而实无以异于凡人。诸生所谓中直者[(10)]，遭时蒙幸[(11)]，备数适然耳[(12)]，殆非明举所谓[(13)]，固未可与论治也[(14)]。”</p><p>【注释】</p><p>[(1)]高第：成绩优异。</p><p>[(2)]智略：智谋。</p><p>[(3)]姿质：通“资质”，指才能、品德等方面综合素质。</p><p>[(4)]居：在家赋闲的时候。</p><p>[(5)]用：用世，当官的时候。为世法：被世人所效法。</p><p>[(6)]道行：谈论施行。</p><p>[(7)]不达：不知道如何去做。《论语·子路》：“授之以政，不达。”</p><p>[(8)]言直而行枉：“行”下原有“之”字，据俞樾说校删。</p><p>[(9)]乡曲：乡里老百姓。</p><p>[(10)]中直：合乎标准而当选，指被郡国推荐作为文学、贤良人选。直，同“值”。</p><p>[(11)]遭时：碰到时机。蒙幸：蒙受幸运。幸，原作“率”，据王先谦说校改。</p><p>[(12)]备数：凑数。适然：出于偶然。</p><p>[(13)]明举：指汉昭帝诏举贤良文学。所谓：诏令中提出推举的标准和要求。</p><p>[(14)]固：本来。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“所谓文学高才，他的智谋应该能够明了先王治国的思想方法，他的资质应该足可以履行先王治国之道。因此，他在家闲居就作为他人老师，做官就被世人所效法。现在文学谈论治国就称颂尧、舜，谈论施行就只能说孔丘、墨翟那一套，将实际政务交给你们，你们又不知道如何去做，怀念古代治国之道而不能在现实中施行，言论正直而行为不正，说的是这一回事，心里想的又是另一回事，穿衣戴帽与乡里老百姓不同，而实际却与平凡人没有两样。这次诸位儒生之所以合乎标准而当选，是因为碰到时机，蒙受幸运，前来凑数，出于偶然罢了，恐怕你们不符合皇上诏令提出推举的标准和要求，本来就不能与你们谈论治理国家大事。”</p><p>文学曰：“天设三光以照记[(1)]，天子立公卿以明治[(2)]。故曰：公卿者，四海之表仪[(3)]，神化之丹青也[(4)]。上有辅明主之任，下有遂圣化之事[(5)]，和阴阳[(6)]，调四时[(7)]，安众庶[(8)]，育群生，使百姓辑睦[(9)]，无怨思之色[(10)]，四夷顺德[(11)]，无叛逆之忧，此公卿之职，而贤者之所务也。若伊尹、周、召三公之才，太颠、闳夭九卿之人[(12)]。文学不中圣主之明举，今之执政，亦未能称盛德也。”</p><p>大夫不说，作色不应也。</p><p>【注释】</p><p>[(1)]三光：日、月、星。照记：照耀。</p><p>[(2)]明治：申明治国之道。</p><p>[(3)]表仪：表率。</p><p>[(4)]神化：神妙感化。丹青：绘画所用的红色和青色颜料，指代绘画，此处引申为榜样。</p><p>[(5)]遂圣化：实现圣贤教化。</p><p>[(6)]和：调和。</p><p>[(7)]调：调理。</p><p>[(8)]众庶：民众。</p><p>[(9)]辑睦：和睦。</p><p>[(10)]怨思：怨恨忧思。</p><p>[(11)]顺德：顺从朝廷的道德感化。</p><p>[(12)]太颠、闳夭：周文王、周武王的大臣。九卿：三公以下的朝廷官员，汉代以太常、郎中令、中大夫令、太仆、大理、大行令、宗正、大司农、少府为九卿。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“上天设置日、月、星三光来照耀天下，天子设立公卿来申明治国之道。所以说，公卿是四海的表率，是神妙感化民众的榜样。公卿对上有辅佐圣明君主的责任，对下有实现圣贤教化的事务，调和阴阳，调理春夏秋冬四季，安定民众，抚育众生，使老百姓和睦，没有怨恨忧思的神色，四夷顺从朝廷的道德感化，没有叛逆的忧患，这些都是朝廷公卿的职责，也是贤士应尽的义务。公卿应该是像伊尹、周公、召公那样的三公贤才，是太颠、闳夭那样的九卿贤人。文学不符合圣明君主的推举标准，当今朝廷执政公卿，也不能称得上是道德高尚吧。”</p><p>大夫不高兴，脸色变了，不作回应。</p><p>文学曰：“朝无忠臣者政闇[(1)]，大夫无直士者位危。任座正言君之过[(2)]，文侯改言行，称为贤君。袁盎面刺绛侯之骄矜[(3)]，卒得其庆[(4)]。故触死亡以干主之过者[(5)]，忠臣也；犯颜以匡公卿之失者[(6)]，直士也。鄙人不能巷言面违[(7)]。方今入谷之教令[(8)]，张而不施[(9)]，食禄多非其人[(10)]，以妨农商工，市井之利，未归于民，民望不塞也[(11)]。且夫帝王之道，多堕坏而不修[(12)]，《诗》云：‘济济多士。’[(13)]意者诚任用其计[(14)]，非苟陈虚言而已[(15)]。”</p><p>【注释】</p><p>[(1)]闇：同“暗”。</p><p>[(2)]任座：战国初期魏文侯的大夫。据《吕氏春秋·自知》载，魏文侯举行宴会，要士大夫谈对他的看法。任座说他是“不肖之君”，魏文侯不悦，任座退出。文侯又问翟璜，翟璜说：“仁君。”文侯说：“怎么知道？”翟说：“君仁，大臣才敢直言，任座刚才知道君仁，故敢直言。”文侯很高兴，让翟璜召回任座，奉他为座上宾。</p><p>[(3)]袁盎面刺绛侯之骄矜：汉文帝时期，周勃上朝见皇帝时表现得很得意。文帝认为周勃是社稷臣，袁盎以为只能说是功臣。周勃知道后怨恨袁盎。后来周勃被罢相，以谋反罪入狱，朝臣不敢为他说情，唯独袁盎为周勃争辩，文帝才释放了周勃。周勃乃与袁盎结交。事见《史记·袁盎晁错列传》。袁盎，西汉前期朝臣。面刺，当面批评。绛侯，周勃，汉家开国功臣，文帝时为右丞相。</p><p>[(4)]庆：吉庆，指袁盎说汉文帝释放周勃。</p><p>[(5)]触死亡：冒着生命危险。干：触犯。</p><p>[(6)]犯颜：触犯尊严。匡：匡正。</p><p>[(7)]鄙人：自称谦词。巷言：在街巷中窃窃私议。违：通“韪”，称是。</p><p>[(8)]方今入谷之教令：原作“方今人主谷之教令”，据黄侃说校改。入谷之教令，指汉代关于庶民用粮食买官的政策。</p><p>[(9)]张：严格执行。施：通“弛”，放松。</p><p>[(10)]食禄多非其人：拿朝廷俸禄的官员多不称职。</p><p>[(11)]望：怨望，怨恨。塞：杜绝。</p><p>[(12)]堕坏：破坏，毁坏。不修：不完备。</p><p>[(13)]济济多士：见于《诗经·大雅·文王》。济济，众多的样子。</p><p>[(14)]诚任用其计：真心采纳他们的建议。</p><p>[(15)]苟陈虚言：随便讲空话。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“朝廷没有忠臣就政治昏暗，大夫身边没有正直敢言之士，地位就危险。当年任座正面指出君主的过错，魏文侯改变言行，被人们称之为贤君。袁盎当面批评绛侯周勃的骄傲自大，周勃最终得到袁盎保释的吉庆。因此冒着生命危险指出君主过错的人是忠臣，触犯尊严匡正公卿过失的人是正直之士。我们不能当面称是背后议论。现在朝廷执行入谷拜爵的政策，抓得很紧，毫不放松，拿朝廷俸禄的官员多不称职，因此妨害农业、商业、手工业，集市等官营利益没有归还给民众，民众怨望绵绵不绝。况且帝王之道，大多被破坏而不完备，《诗经·大雅·文王》说：‘人才济济。’诗句大意是说要真心采用贤士的计谋，而不是随便说几句空话就行的。”</p>',195)])])}const z=l(n,[["render",s]]);export{y as __pageData,z as default};
